import "server-only";import {and,eq,ne,sql} from "drizzle-orm";import {db} from "@/db";import {adminAuditLogs,rankedChallengeItems,rankedChallenges} from "@/db/schema";import {getFullMockReadiness} from "@/lib/full-mock/service";import {CHALLENGE_POLICY} from "./policy";import type {ChallengeType} from "@/lib/gamification/catalog";
export async function createChallengeDraft(actorUserId:string,input:{type:ChallengeType;titleEn:string;titleVi:string;startsAt:Date;endsAt:Date}){if(!CHALLENGE_POLICY[input.type]||!input.titleEn||!input.titleVi||!Number.isFinite(input.startsAt.getTime())||!Number.isFinite(input.endsAt.getTime())||input.endsAt<=input.startsAt||input.endsAt.getTime()-input.startsAt.getTime()<CHALLENGE_POLICY[input.type].durationMs)throw new Error("INVALID_CHALLENGE");return db.transaction(async tx=>{await tx.execute(sql`select pg_advisory_xact_lock(hashtextextended(${`challenge:${input.type}`},0))`);const overlap=await tx.select({id:rankedChallenges.id}).from(rankedChallenges).where(and(eq(rankedChallenges.type,input.type),eq(rankedChallenges.status,"PUBLISHED"),sql`${rankedChallenges.startsAt}<${input.endsAt} and ${rankedChallenges.endsAt}>${input.startsAt}`)).limit(1);if(overlap.length)throw new Error("OVERLAPPING_CHALLENGE");const[c]=await tx.insert(rankedChallenges).values({...input,createdBy:actorUserId}).returning();await tx.insert(adminAuditLogs).values({actorUserId,action:"CHALLENGE_DRAFT_CREATED",metadata:{challengeId:c.id,type:c.type}});return c.id;});}
export async function generateChallengeForm(actorUserId:string,id:string){const ready=await getFullMockReadiness();if(!ready.ready||!ready.form)throw new Error("CONTENT_NOT_READY");return db.transaction(async tx=>{const[c]=await tx.select().from(rankedChallenges).where(eq(rankedChallenges.id,id)).for("update").limit(1);if(!c||c.status!=="DRAFT")throw new Error("IMMUTABLE");const policy=CHALLENGE_POLICY[c.type as ChallengeType];const units=policy.parts.flatMap(part=>ready.form!.byPart[part]??[]);const items=units.flatMap(u=>u.questionIds.map(q=>({part:u.part,questionId:q,groupId:u.part===5?null:u.id})));if(items.length!==policy.questions)throw new Error("INVALID_BLUEPRINT");await tx.delete(rankedChallengeItems).where(eq(rankedChallengeItems.challengeId,id));await tx.insert(rankedChallengeItems).values(items.map((x,i)=>({challengeId:id,position:i+1,...x})));await tx.insert(adminAuditLogs).values({actorUserId,action:"CHALLENGE_FORM_GENERATED",metadata:{challengeId:id,questions:items.length}});return items.length;});}
export async function publishChallenge(actorUserId:string,id:string){return db.transaction(async tx=>{const[c]=await tx.select().from(rankedChallenges).where(eq(rankedChallenges.id,id)).for("update").limit(1);if(c?.status==="PUBLISHED")return false;if(!c||c.status!=="DRAFT"||!c.startsAt||!c.endsAt)throw new Error("INVALID_LIFECYCLE");const [{count}]=await tx.select({count:sql<number>`count(*)::int`}).from(rankedChallengeItems).where(eq(rankedChallengeItems.challengeId,id));if(Number(count)!==CHALLENGE_POLICY[c.type as ChallengeType].questions)throw new Error("INVALID_FORM");const invalid=await tx.execute(sql`select 1 from ranked_challenge_items i join questions q on q.id=i.question_id left join passage_sets g on g.id=i.group_id where i.challenge_id=${id} and (q.status<>'published' or (i.group_id is not null and g.status<>'published')) limit 1`);if(invalid.rows.length)throw new Error("INVALID_FORM");await tx.update(rankedChallenges).set({status:"PUBLISHED",publishedAt:new Date(),updatedAt:new Date()}).where(eq(rankedChallenges.id,id));await tx.insert(adminAuditLogs).values({actorUserId,action:"CHALLENGE_PUBLISHED",metadata:{challengeId:id}});return true;});}
export async function cancelChallenge(actorUserId:string,id:string){return db.transaction(async tx=>{const[c]=await tx.select().from(rankedChallenges).where(and(eq(rankedChallenges.id,id),ne(rankedChallenges.status,"CANCELLED"))).for("update").limit(1);if(!c)return false;await tx.update(rankedChallenges).set({status:"CANCELLED",cancelledAt:new Date(),updatedAt:new Date()}).where(eq(rankedChallenges.id,id));await tx.insert(adminAuditLogs).values({actorUserId,action:"CHALLENGE_CANCELLED",metadata:{challengeId:id}});return true;});}
