"use server";import{redirect}from"next/navigation";import{revalidatePath}from"next/cache";import{requireAdmin}from"@/lib/admin/authorization";import{cancelChallenge,createChallengeDraft,generateChallengeForm,publishChallenge}from"@/lib/challenges/admin";import type{ChallengeType}from"@/lib/gamification/catalog";
const val=(f:FormData,k:string)=>String(f.get(k)??"").trim();export async function createChallengeAction(f:FormData){const a=await requireAdmin("CHALLENGE_MANAGE");let id="";try{const type=val(f,"type");if(!["READING_100","LISTENING_100","FULL_200"].includes(type))throw new Error("INVALID_TYPE");const parseVietnamTime=(value:string)=>{if(!/^\d{4}-\d\d-\d\dT\d\d:\d\d$/.test(value))throw new Error("INVALID_DATE");return new Date(`${value}:00+07:00`)};id=await createChallengeDraft(a.id,{type:type as ChallengeType,titleEn:val(f,"titleEn"),titleVi:val(f,"titleVi"),startsAt:parseVietnamTime(val(f,"startsAt")),endsAt:parseVietnamTime(val(f,"endsAt"))});}catch{redirect("/admin/challenges/new?error=invalid");}redirect(`/admin/challenges/${id}`)}
export async function generateFormAction(id:string){const a=await requireAdmin("CHALLENGE_MANAGE");try{await generateChallengeForm(a.id,id);revalidatePath(`/admin/challenges/${id}`);}catch{redirect(`/admin/challenges/${id}?error=generate`);}}
export async function publishChallengeAction(id:string){const a=await requireAdmin("CHALLENGE_MANAGE");try{await publishChallenge(a.id,id);revalidatePath("/admin/challenges");}catch{redirect(`/admin/challenges/${id}?error=publish`);}}
export async function cancelChallengeAction(id:string){const a=await requireAdmin("CHALLENGE_MANAGE");await cancelChallenge(a.id,id);revalidatePath("/admin/challenges");}
